#include <string>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::string value = "red apple";
    value.replace(0, 3, "green");
    assert(value == "green apple" && value != "red apple");
    auto allocator = value.get_allocator();
    (void)allocator;
    assert(std::stof("1.5") == 1.5f);
    assert(std::stoul("123") == 123ul);
}
